(()=>{'use strict';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const dialog=$('#detail-dialog');
const details={
framework:{label:'JEV / RESEARCH FRAMEWORK',title:'From experiments<br>to continuous estimates.',body:`<p>JEV combines a fixed pretrained model's range decision with labelled experimental context and measured neighbours to produce a traceable adsorption capacity estimate.</p><div class="detail-grid"><div class="detail-step"><small>01 / CONTEXT</small><h3>Experimental context</h3><p>Six state fields—pyrolysis temperature, solution pH, initial concentration, BET area, contact time and biochar pH—retrieve eight same-metal references.</p></div><div class="detail-step"><small>02 / RANGE</small><h3>Capacity range selection</h3><p>JEV returns range probabilities pᵢ and confidence c with fixed pretrained parameters. Pb boundaries of 2, 8, 16, 30 and 60 mg/g define six ranges.</p></div><div class="detail-step"><small>03 / EVIDENCE</small><h3>Two retrieval routes</h3><p>Eleven descriptors rank the global and range-specific candidates. Missing values use pool statistics; descriptors are standardized within the pool. Matching feedstocks receive a −1.5 ranking offset.</p></div><div class="detail-step"><small>04 / ESTIMATION</small><h3>Log-space fusion</h3><p>Local QB and global QG evidence are combined into continuous Qe while retaining the selected records and decision path.</p></div></div><p class="formula">QF = QB<sup>α</sup> × QG<sup>1−α</sup></p><p>Confidence c is a range decision score. Continuous prediction intervals and external validity require further evaluation.</p><img src="assets/jev-workflow.svg" alt="Experimental context, range selection and neighbour fusion workflow">`},
range:{label:'RESEARCH 01 / RANGE INTELLIGENCE',title:'A range before<br>a number.',body:`<p>A capacity range provides a local constraint for retrieving experimentally similar records. The probability distribution preserves uncertainty in the range decision.</p><h3>Six Pb capacity ranges</h3><p class="formula">2 · 8 · 16 · 30 · 60 <small>mg/g</small></p><p>In the illustrative query, JEV selects B3: 8 ≤ Qe &lt; 16 mg/g. Its probability is 0.93 and returned confidence c is 0.91.</p><h3>From selection to retrieval</h3><p>Of 279 Pb candidates, 77 belong to the selected range. Descriptor similarity then ranks this local evidence pool.</p><p>Range probabilities and confidence c describe the discrete decision; they do not define a calibrated continuous Qe interval.</p>`},
retrieval:{label:'RESEARCH 02 / EMPIRICAL RETRIEVAL',title:'Experiments provide<br>the context.',body:`<p>Material properties and operating conditions jointly shape adsorption performance. JEV retrieves labelled context using the experimental state and ranks final candidates using a broader descriptor set.</p><div class="detail-grid"><div class="detail-step"><small>CONTEXT / SIX FIELDS</small><h3>Six state fields</h3><p>Pyrolysis temperature, solution pH, initial concentration, BET area, contact time and biochar pH retrieve eight same-metal neighbours.</p></div><div class="detail-step"><small>RANKING / ELEVEN DESCRIPTORS</small><h3>Eleven descriptors</h3><p>Final retrieval uses pool-specific imputation and standardization, with a −1.5 offset for matching feedstocks.</p></div></div><h3>Every candidate links to a measured record</h3><p>The Pb example retains all 279 global candidates and 77 range-specific candidates. Downloaded data include measured capacities, range membership and neighbour flags.</p><a class="outline-button" href="assets/pb-candidate-rank-qe.csv" download>DOWNLOAD CANDIDATES <span>↓</span></a>`},
fusion:{label:'RESEARCH 03 / CONTINUOUS ESTIMATION',title:'Two evidence routes.<br>One traceable estimate.',body:`<p>The local neighbour QB and global neighbour QG provide complementary evidence. Log-space weighting converts a discrete range decision into a continuous estimate.</p><p class="formula">QF = QB<sup>α</sup> × QG<sup>1−α</sup></p><h3>A traceable Pb example</h3><p>Pyrolysis temperature: 500 °C. Solution pH: 5. Initial concentration: 40 mg/L. BET area: 208.4 m²/g. Selected range: 8–16 mg/g. Global QG = 7 mg/g; local QB = 10 mg/g.</p><p class="formula">10<sup>0.4</sup> × 7<sup>0.6</sup> ≈ 8.07 mg/g</p><p>With α = 0.4 and k = 1, this example matches measured Qe = 8.07 mg/g. It illustrates traceability rather than a guarantee for unseen materials.</p>`},
metal:{label:'VALIDATION / METAL ADSORPTION',title:'Pb & Cd.<br>Retrospective evaluation.',body:`<p>The dataset contains 556 records: 349 Pb and 207 Cd. The development set contains 445 records; the evaluation set contains 111 (70 Pb and 41 Cd).</p><table><thead><tr><th>Method</th><th>MAE</th><th>95% interval</th></tr></thead><tbody><tr><td>JEV fusion</td><td>0.111</td><td>0.076–0.152</td></tr><tr><td>Nearest neighbour</td><td>0.119</td><td>0.084–0.160</td></tr><tr><td>LightGBM</td><td>0.123</td><td>0.091–0.159</td></tr></tbody></table><p>Errors use log₁₀ capacity units. Fusion R² is 0.918; Pb and Cd R² are 0.828 and 0.926 respectively.</p><p>Early development inspected 25 of the 111 evaluation records, so the assessment is retrospective. Record-level splitting may also retain related experiments across sets.</p><p>MAE intervals overlap. These selected comparisons do not establish statistically significant superiority; archived tree ensembles achieve lower MAE. New materials and conditions require external validation.</p>`},
organic:{label:'VALIDATION / ORGANIC CONTEXTS',title:'Adapting through<br>labelled context.',body:`<p>The organic EC evaluation includes 98 records across 14 pollutant labels, some of which may represent aliases. Labelled target context supports the predictions.</p><table><thead><tr><th>Method</th><th>MAE</th></tr></thead><tbody><tr><td>Geometric midpoint</td><td>0.252</td></tr><tr><td>Nearest neighbour</td><td>0.152</td></tr><tr><td>Fusion</td><td>0.148</td></tr></tbody></table><p>Fusion R² is 0.777. Errors use log₁₀ capacity units. The paired fusion improvement interval includes zero.</p><h3>Context adaptation</h3><p>Target conditions and labelled references inform capacity ranges and retrieval. Evaluation of new pollutant classes requires suitable data coverage and comparable experiments.</p>`},
case:{label:'TRACEABLE EXAMPLE / PB',title:'279 records.<br>A visible decision path.',body:`<p>The selected 8–16 mg/g range contains 77 of the 279 global candidates. Descriptor distances rank these records for local neighbour selection.</p><p>The global nearest neighbour ranks first and has QG = 7 mg/g. The local neighbour ranks third globally and has QB = 10 mg/g. With α = 0.4 and k = 1, QF ≈ 8.07 mg/g.</p><img src="assets/pb-candidate-cloud.svg" alt="Measured capacities and neighbour flags for 279 Pb candidates"><p>Measured Qe for this example is 8.07 mg/g. The example illustrates an auditable path; overall performance is assessed across the evaluation records.</p><a class="outline-button" href="assets/pb-candidate-rank-qe.csv" download>DOWNLOAD DATA <span>↓</span></a>`}
};
function openDialog(d){d.showModal();document.body.classList.add('modal-open')}
function closeDialog(d){d.close();document.body.classList.remove('modal-open')}
all('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.classList.remove('modal-open'));d.querySelector('[data-close]').addEventListener('click',()=>closeDialog(d));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function showDetail(key){const t=details[key];$('#detail-content').innerHTML=`<p class="eyebrow">${t.label}</p><h2>${t.title}</h2>${t.body}`;openDialog(dialog);dialog.scrollTop=0}
all('[data-detail]').forEach(b=>b.addEventListener('click',()=>showDetail(b.dataset.detail)));
$('#open-menu').addEventListener('click',()=>openDialog($('#navigation-dialog')));
all('#navigation-dialog nav a').forEach(a=>a.addEventListener('click',()=>closeDialog($('#navigation-dialog'))));
const notes={metal:'Retrospective record-level evaluation. MAE intervals overlap; selected comparisons do not establish universal superiority.',organic:'Labelled target context. Results refer to 98 EC evaluation records across 14 pollutant labels.',case:'A traceable example rather than an overall performance estimate. Candidate data are available for download.'};
let selected='metal';
function cover(key){const head=`<svg class="chart-cover" viewBox="0 0 480 540" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${key==='metal'?'Metal evaluation MAE and confidence intervals':key==='organic'?'Organic evaluation MAE comparison':'Pb example evidence fusion'}"><rect x="30" y="25" width="420" height="490" fill="white"/><text x="61" y="61" font-family="Arial" font-size="10" fill="#c8005f" letter-spacing="2">JEV / RESEARCH EVIDENCE</text>`;let b='';
if(key==='case'){b=`<text x="61" y="111" font-size="34" fill="#182f54" font-family="Arial">A traceable estimate.</text><text x="61" y="139" font-size="12" fill="#777" font-family="Arial">Pb · 279 candidates · 77 in range</text><path d="M110 260 Q240 180 365 260M110 260 Q240 360 365 260" fill="none" stroke="#ccd1db" stroke-width="2"/><circle cx="110" cy="260" r="38" fill="#182f54"/><circle cx="365" cy="260" r="38" fill="#c8005f"/><circle cx="237" cy="260" r="48" fill="#f4e6ed"/><g font-family="Arial" text-anchor="middle"><text x="110" y="268" fill="white" font-size="25">7</text><text x="365" y="268" fill="white" font-size="25">10</text><text x="237" y="268" fill="#c8005f" font-size="29">8.07</text><text x="110" y="323" fill="#777" font-size="10">GLOBAL QG</text><text x="365" y="323" fill="#777" font-size="10">RANGE QB</text><text x="237" y="380" fill="#182f54" font-size="15">QF = 10⁰·⁴ × 7⁰·⁶</text></g><text x="61" y="454" font-family="Arial" font-size="10" fill="#777">α = 0.4 · k = 1 · Qe in mg/g</text>`}else{const metal=key==='metal',values=metal?[.111,.119,.123]:[.252,.152,.148],labels=metal?['JEV','Nearest neighbour','LightGBM']:['Geometric midpoint','Nearest neighbour','Fusion'],max=metal?.18:.30;b=`<text x="61" y="110" font-family="Arial" font-size="33" fill="#182f54">${metal?'Pb & Cd evaluation.':'Organic adaptation.'}</text><text x="61" y="139" font-family="Arial" font-size="12" fill="#777">${metal?'111 records · retrospective evaluation':'98 records · 14 pollutant labels · MAE'}</text>`;for(let j=0;j<4;j++){const x=70+j*107;b+=`<path d="M${x} 178V365" stroke="#e8eaf0"/><text x="${x}" y="386" text-anchor="middle" font-size="10" font-family="Arial" fill="#888">${(j*max/3).toFixed(2)}</text>`}values.forEach((v,i)=>{const y=202+i*64,w=v/max*321,c=(metal?i===0:i===2)?'#c8005f':'#182f54';b+=`<text x="70" y="${y-9}" fill="#182f54" font-size="11" font-family="Arial">${labels[i]}</text><rect x="70" y="${y}" width="${w}" height="16" fill="${c}"/><text x="${Math.min(405,80+w)}" y="${y+12}" fill="${c}" font-size="12" font-family="Arial">${v.toFixed(3)}</text>`;if(metal){const lows=[.076,.084,.091],highs=[.152,.16,.159],xl=70+lows[i]/max*321,xh=70+highs[i]/max*321;b+=`<path d="M${xl} ${y+8}H${xh}M${xl} ${y+2}V${y+14}M${xh} ${y+2}V${y+14}" stroke="#4d5970" stroke-width="1.5"/>`}});b+=`<text x="61" y="443" font-size="37" fill="#c8005f" font-family="Arial">R² ${metal?'0.918':'0.777'}</text><text x="61" y="470" fill="#888" font-size="10" font-family="Arial">${metal?'Confidence intervals overlap.':'Labelled target context; not zero-shot.'}</text>`}return head+b+'</svg>'}
function selectEvidence(key){selected=key;all('.evidence-row').forEach(b=>{const a=b.dataset.evidence===key;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a)});$('#evidence-feature').innerHTML=cover(key);$('#evidence-note').textContent=notes[key]}
all('.evidence-row').forEach(b=>{['mouseenter','focus','click'].forEach(event=>b.addEventListener(event,()=>selectEvidence(b.dataset.evidence)))});$('#evidence-details').addEventListener('click',()=>showDetail(selected));selectEvidence('metal');
const figures=['fig1_jev_evidence_and_choice','fig2_jev_range_filter_and_fusion','fig3_jev_improvement_and_benchmarks','fig4_jev_probability_and_confidence','fig5_jev_validation_and_context_adaptation'];const titles=['Evidence & choice','Range & fusion','Improvement & benchmarks','Probability & confidence','Validation & adaptation'];
all('[data-figure]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.figure)-1,base='assets/research/'+figures[i];$('#figure-label').textContent='JEV RESEARCH / FIGURE 0'+(i+1);$('#figure-title').textContent=titles[i];$('#figure-image').src=base+'.svg';$('#figure-image').alt=titles[i];$('#figure-pdf').href=base+'.pdf';$('#figure-svg').href=base+'.svg';openDialog($('#figure-dialog'));$('#figure-dialog').scrollTop=0}));
['prev','next'].forEach((k,i)=>$('#library-'+k).addEventListener('click',()=>{const track=$('#library-track');track.scrollBy({left:(track.querySelector('button').offsetWidth+25)*(i?1:-1),behavior:'smooth'})}));
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function motion(){const b=$('#motion-toggle');b.setAttribute('aria-pressed',paused);b.innerHTML=(paused?'▶':'Ⅱ')+' <span>'+(paused?'PLAY MOTION':'PAUSE MOTION')+'</span>';window.JEVScene?.setPaused(paused)}$('#motion-toggle').addEventListener('click',()=>{paused=!paused;motion()});motion();
let ticking=false;function update(){const r=$('#about').getBoundingClientRect(),progress=Math.max(0,Math.min(1,-r.top/(r.height-innerHeight)));$('#about').style.setProperty('--progress',progress);$('#header').classList.toggle('dark',r.top<82&&r.bottom>100);$('.back-top').classList.toggle('visible',scrollY>innerHeight*.8);if(innerWidth>650&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const rr=$('#research').getBoundingClientRect(),p=Math.max(-1,Math.min(1,(innerHeight*.55-rr.top-rr.height*.45)/innerHeight));all('.research-card').forEach((b,i)=>b.style.setProperty('--shift',((i===1?-1:1)*p*42)+'px'))}ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true});addEventListener('resize',update);update();
})();
